    junior: `const App = () => {
  const [seconds, setSeconds] = useState(0);
  const [intervalId, setIntervalId] = useState(null);

  const handleStart = () => {
    if (intervalId !== null) {
      return;
    }
    const id = setInterval(() => {
      setSeconds((current) => current + 1);
    }, 1000);
    setIntervalId(id);
  };

  const handleStop = () => {
    if (intervalId !== null) {
      clearInterval(intervalId);
      setIntervalId(null);
    }
  };

  const handleReset = () => {
    handleStop();
    setSeconds(0);
  };

  useEffect(() => {
    return () => {
      if (intervalId !== null) {
        clearInterval(intervalId);
      }
    };
  }, [intervalId]);

  return (
    <main>
      <p>{seconds} s</p>
      <button onClick={handleStart}>Start</button>
      <button onClick={handleStop}>Stop</button>
      <button onClick={handleReset}>Reset</button>
    </main>
  );
};`,
    senior: `const useInterval = (callback, delay) => {
  const saved = useRef(callback);
  useEffect(() => { saved.current = callback; }, [callback]);
  useEffect(() => {
    if (delay === null) return undefined;
    const id = setInterval(() => saved.current(), delay);
    return () => clearInterval(id);
  }, [delay]);
};

const App = () => {
  const [seconds, setSeconds] = useState(0);
  const [running, setRunning] = useState(false);
  useInterval(() => setSeconds(current => current + 1), running ? 1000 : null);

  const reset = () => {
    setRunning(false);
    setSeconds(0);
  };

  return (
    <main>
      <p>{seconds}s</p>
      <button type="button" onClick={() => setRunning(true)} disabled={running}>Start</button>
      <button type="button" onClick={() => setRunning(false)} disabled={!running}>Stop</button>
      <button type="button" onClick={reset}>Reset</button>
    </main>
  );
};`,
